<?php require_once('dbstring.php');require_once('website-content-utils.php');$items=aps_gallery_items($con);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gallery | Awuah Preparatory School</title><style>body{margin:0;background:#f3f7fa;color:#183650;font:16px Arial}.wrap{max-width:1120px;margin:40px auto;padding:0 20px}a{color:#08766f;font-weight:bold}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:18px;margin-top:24px}.item{margin:0;background:#fff;border:1px solid #d7e2ea;border-radius:12px;overflow:hidden;box-shadow:0 7px 18px rgba(22,54,86,.06)}.item img{width:100%;height:210px;object-fit:cover;display:block}.item figcaption{padding:13px;font-weight:bold}.empty{padding:28px;background:#fff;border-radius:12px}</style></head><body><main class="wrap"><a href="website.php">← Awuah Preparatory School</a><h1>School gallery</h1><p>Moments from learning, play, achievement, and school life.</p><?php if(empty($items)){?><p class="empty">Our gallery is being prepared. Please check back soon.</p><?php }else{?><div class="grid"><?php foreach($items as $item){?><figure class="item"><img loading="lazy" src="<?php echo aps_website_escape($item['image_path']);?>" alt="<?php echo aps_website_escape($item['caption']);?>"><figcaption><?php echo aps_website_escape($item['caption']);?></figcaption></figure><?php }?></div><?php }?></main></body></html>
